<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { api } from '../../api'; import { fetchUsers, fetchRoles, assignUserRole } from '../../api/system'; import UserTable from '../../components/UserTable.vue'; import UserForm from '../../components/UserForm.vue'; import CustomerPagination from '../../components/CustomerPagination.vue'; import { useAuthStore } from '../../stores/auth';
const auth=useAuthStore(); const users=ref<any[]>([]); const roles=ref<any[]>([]); const page=ref(1); const size=ref(10); const total=ref(0); const dialog=ref(false);
async function load(){try{const [u,r]=await Promise.all([fetchUsers(page.value,size.value),fetchRoles(1,100)]);users.value=u.data.data.items;total.value=u.data.data.total;roles.value=r.data.data.items;}catch{ElMessage.error('用户数据加载失败');}}
async function create(payload:any){try{await api.post('/system/users',payload);dialog.value=false;await load();}catch{ElMessage.error('用户创建失败');}} async function toggle(u:any){try{await api.put(`/system/users/${u.id}/enabled`,null,{params:{enabled:!u.enabled}});await load();}catch{ElMessage.error('状态更新失败');}} async function assignRole(u:any,c:string){try{await assignUserRole(u.id,c);await load();}catch{ElMessage.error('角色分配失败');}} onMounted(load);
</script>
<template><el-card><template #header><div class="header"><span>用户管理</span><el-button v-if="auth.hasPermission('system:user:write')" type="primary" @click="dialog=true">新增用户</el-button></div></template><UserTable :users="users" :roles="roles" :can-write="auth.hasPermission('system:user:write')" @toggle="toggle" @assign-role="assignRole"/><CustomerPagination :page="page" :size="size" :total="total" @update:page="page=$event;load()" @update:size="size=$event;page=1;load()"/></el-card><UserForm v-model="dialog" @save="create" /></template>
<style scoped>.header{display:flex;justify-content:space-between;align-items:center}</style>
